let azCandidateHold=null,azCandidateBlocked=null,azCandidateBlockUntil=0;
function azCancelCandidateHold(){if(azCandidateHold){clearTimeout(azCandidateHold.timer);azCandidateHold=null;}}
azPick.addEventListener('pointerdown',e=>{
  azCancelCandidateHold();
  const b=e.target.closest('[data-candidate]');
  if(!b||e.isPrimary===false||(e.pointerType==='mouse'&&e.button!==0))return;
  azCandidateBlocked=null;
  const p={button:b,id:e.pointerId,x:e.clientX,y:e.clientY,timer:null};
  azCandidateHold=p;
  p.timer=setTimeout(()=>{
    if(azCandidateHold!==p)return;
    azCandidateHold=null;
    if(!azPick.open||!b.isConnected||!tavRec(b.dataset.candidate))return;
    azCandidateBlocked=b;azCandidateBlockUntil=Infinity;
    azInspect(b.dataset.candidate,b);
  },800);
});
document.addEventListener('pointermove',e=>{
  const p=azCandidateHold;
  if(p&&e.pointerId===p.id&&Math.hypot(e.clientX-p.x,e.clientY-p.y)>10)azCancelCandidateHold();
},true);
function azEndCandidateHold(){azCancelCandidateHold();if(azCandidateBlocked)azCandidateBlockUntil=performance.now()+1000;}
document.addEventListener('pointerup',azEndCandidateHold,true);
document.addEventListener('pointercancel',azEndCandidateHold,true);
azPick.addEventListener('scroll',azCancelCandidateHold,true);
azPick.addEventListener('close',()=>{azCancelCandidateHold();azCandidateBlocked=null;});
azPick.addEventListener('contextmenu',e=>{if(e.target.closest('[data-candidate]'))e.preventDefault();});
azPick.addEventListener('click',e=>{
  const b=e.target.closest('[data-candidate]');
  if(b&&b===azCandidateBlocked&&performance.now()<=azCandidateBlockUntil){
    e.preventDefault();e.stopImmediatePropagation();azCandidateBlocked=null;
  }
},true);
const azDetail=document.createElement('dialog');
